import { formatTemplate, mergeProperty, minimumAgeOf as sharedMinimumAgeOf, propertyTokens } from '@trelliskit/shared';
import Constants from 'expo-constants';

/**
 * Property configuration for the app (docs/TRELLISKIT.md sections 2 and 5).
 *
 * The app is the engine; everything about the property (name, owner, minimum age, profile
 * taxonomy, store product id, domains, colors) comes from the property configuration. The
 * bundled copy (extra.property, generated by app.config.js from the active property folder) is
 * used at launch and offline; PropertyProvider merges GET /api/v1/property over it when that
 * loads. Profile field definitions (profileFieldsOf) and tokens come from @trelliskit/shared.
 */

let bundled = null;

/**
 * The property bundled at build time (app.config.js extra.property).
 * @returns {object}
 */
export function getBundledProperty() {
  if (!bundled) {
    const extra = (Constants.expoConfig && Constants.expoConfig.extra) || {};
    bundled = Object.freeze(extra.property && typeof extra.property === 'object' ? extra.property : {});
  }
  return bundled;
}

/**
 * Merge the runtime property (GET /api/v1/property) over the bundled copy. Invalid or missing
 * runtime values keep the bundled copy.
 * @param {object} base
 * @param {object|null} runtime
 * @returns {object}
 */
export function resolveProperty(base, runtime) {
  if (!runtime || typeof runtime !== 'object') return base;
  const { web: _web, ...rest } = runtime;
  return mergeProperty(base, rest);
}

/**
 * Apply `{token}` substitution to every string in a nested structure. Functions are wrapped so
 * their results are filled too. Unknown tokens are left as they are.
 * @template T
 * @param {T} value
 * @param {Record<string, string|number>} values
 * @returns {T}
 */
export function fillDeep(value, values) {
  if (typeof value === 'string') return formatTemplate(value, values);
  if (typeof value === 'function') return (...args) => fillDeep(value(...args), values);
  if (Array.isArray(value)) return Object.freeze(value.map((item) => fillDeep(item, values)));
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value)) out[key] = fillDeep(value[key], values);
    return Object.freeze(out);
  }
  return value;
}

/**
 * Fill a nested strings template from a property's tokens ({name}, {owner}, {minimumAge}, ...).
 * @template T
 * @param {T} template
 * @param {object} property
 * @returns {T}
 */
export function fillFromProperty(template, property) {
  return fillDeep(template, propertyTokens(property));
}

/**
 * Minimum age to join: `minimumAge` from GET /api/v1/property (always present, also in the Open
 * access model where `membership` is null), else `membership.minimumAge`, else 18.
 */
export function minimumAgeOf(property) {
  return sharedMinimumAgeOf(property);
}

/** Membership store product id from the property, or null. */
export function storeProductIdOf(property) {
  const value = property && property.membership && property.membership.storeProductId;
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

/**
 * Page URL on the property's web domain (domains.web), for example the legal pages.
 * @param {object} property
 * @param {string} pathname Starting with "/".
 * @returns {string|null}
 */
export function webUrl(property, pathname) {
  const domain = property && property.domains && property.domains.web;
  return domain ? 'https://' + domain + pathname : null;
}
